import { DensityProvider, Label, Switch, useDensity } from "@wunderui/react"

function DensitySetting() {
  const { density, setDensity } = useDensity()
  return (
    <Label className="flex items-center gap-3">
      <Switch checked={density === "comfortable"} onCheckedChange={(on) => setDensity(on ? "comfortable" : "compact")} />
      Comfortable spacing
    </Label>
  )
}

export function App({ children }: { children: React.ReactNode }) {
  return <DensityProvider storageKey="wui-density">{children}</DensityProvider>
}

import * as React from "react"
import { useScrollSpy } from "@wunderui/react"

const sections = ["overview", "billing", "members"]

export function SettingsPanel() {
  const box = React.useRef<HTMLDivElement>(null)
  const [active] = useScrollSpy(sections, box)
  return (
    <div className="flex gap-4">
      <nav aria-label="Sections" className="flex flex-col gap-1 text-sm">
        {sections.map((id) => (
          <a key={id} href={`#${id}`} aria-current={active === id ? "true" : undefined} className={active === id ? "font-medium text-foreground" : "text-text-secondary"}>
            {id}
          </a>
        ))}
      </nav>
      <div ref={box} className="h-48 overflow-y-auto">
        {sections.map((id) => (
          <section key={id} id={id} className="min-h-40">…</section>
        ))}
      </div>
    </div>
  )
}

